'use strict';
// Whole-published-catalog discoverability and TAT regression audit.
// The source indexes are generated by the calculators' actual catalog loaders.
const { test } = require('node:test');
const assert = require('node:assert/strict');
const { readFileSync } = require('node:fs');
const { resolve } = require('node:path');
const vm = require('node:vm');
const openCalculator = require('./helpers/calculator-vm.cjs');

const read = path => readFileSync(resolve(__dirname, '..', path), 'utf8');
function moduleWindow(path) {
  const window = {};
  vm.runInNewContext(read(path), { window }, {filename: path, timeout: 30000});
  return window;
}
const clinical = moduleWindow('assets/js/clinical-categories.js').LabClinicalCategories;
const clinicalIds = new Set(clinical.options.map(item => item.id));

for (const [lab, page, app] of [
  ['quest', 'index.html', 'assets/js/app.js'],
  ['labcorp', 'labcorp.html', 'labcorp-app.js']
]) {
  test(lab + ': every published active test is searchable, filterable, and shows available TAT', {timeout: 120000}, () => {
    const rows = JSON.parse(read('assets/search/' + lab + '-tests.json')).tests;
    assert(rows.length >= (lab === 'quest' ? 3000 : 5000), 'Catalog index appears incomplete');
    const records = rows.map(([code, name, specimen, aliases]) => ({
      id: 'audit-' + code, testCode: code, testName: name,
      specimenType: specimen, source: 'Lab Directory', status: 'active',
      searchAliases: aliases,
      clinicalCategories: aliases.filter(alias => clinicalIds.has(alias))
    }));
    const directory = moduleWindow('assets/js/' + lab + '-directory-tat.js').LabDirectoryTat;
    const { database, rankLibraryTest, specimenFilterCategories,
      specimenFilterCategoriesForType, regionalDirectoryTat, hasRoutineTat, tatBadge } =
      openCalculator(app, ['database', 'rankLibraryTest', 'specimenFilterCategories',
        'specimenFilterCategoriesForType', 'regionalDirectoryTat', 'hasRoutineTat', 'tatBadge'],
        { records, window: { LabClinicalCategories: clinical, LabDirectoryTat: directory } });
    const byCode = new Map(database.map(item => [item.testCode, item]));
    const markup = read(page);
    const selector = markup.split('<select id="specimenFilter"')[1]?.split('</select>')[0] || '';
    const specimenOptions = new Set([...selector.matchAll(/<option[^>]*value="([^"]+)"/g)]
      .map(match => match[1]));

    for (const [code, name] of rows) {
      const row = byCode.get(code);
      assert(row, lab + ' code missing from calculator: ' + code);
      assert.equal(rankLibraryTest(code, row), 2000, lab + ' exact code: ' + code);
      assert(rankLibraryTest(name, row) >= 500, lab + ' name search: ' + code);
      const availableSpecimenCategories = specimenFilterCategories(row);
      assert(availableSpecimenCategories.some(cat => specimenOptions.has(cat)),
        lab + ' specimen filter not selectable: ' + code);
      const assignedClinical = clinical.forTest(row);
      assert(assignedClinical.length && assignedClinical.every(id => clinicalIds.has(id)),
        lab + ' category filter not selectable: ' + code);
      const hasPublishedTat = Object.values(directory)
        .some(area => Boolean(area?.[code]?.[0]));
      assert.equal(Boolean(hasRoutineTat(row)), hasPublishedTat,
        lab + ' routine TAT lookup: ' + code);
      assert.equal(tatBadge(row).includes('data-action="view-tat"'), hasPublishedTat,
        lab + ' TAT clock visibility: ' + code);
    }

    assert(specimenOptions.has('Respiratory'), lab + ' missing respiratory filter');
    for (const respiratory of ['Bronchoalveolar Lavage', 'Bronchial Washing',
      'Tracheal Aspirate', 'Nasopharyngeal Washing']) {
      assert(specimenFilterCategoriesForType(respiratory).includes('Respiratory'),
        lab + ' respiratory specimen miscategorized: ' + respiratory);
    }
    assert(specimenFilterCategoriesForType('Calculi').includes('Dry Stone'));
    assert(specimenFilterCategoriesForType('Bile').includes('Body Fluid'));

    if (lab === 'labcorp') {
      const calcium = byCode.get('001016');
      assert(calcium);
      assert.equal(regionalDirectoryTat(calcium, 'socal')?.[0],
        regionalDirectoryTat(calcium, 'directory')?.[0],
        'General Labcorp TAT must remain visible when regional TAT is missing');
      assert.equal(regionalDirectoryTat(calcium, 'ny')?.[0],
        regionalDirectoryTat(calcium, 'directory')?.[0]);
      const code = read(app);
      assert(code.includes("localStorage.setItem(TAT_REGION_KEY, $('tatRegionFilter').value)"),
        'Selected Labcorp TAT region must be saved');
      assert(code.includes('not verified for ' + "' + regionLabel + '"),
        'General Labcorp TAT must not be labeled as regional verification');
    }
  });
}
